"""Self-contained PC control panel. No external scripts, fonts, or assets."""

HTML = '''<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>智调 · AI 硬件调试控制台</title>
<style nonce="__NONCE__">
:root{font-family:"Segoe UI","Microsoft YaHei",system-ui,sans-serif;color:#172c42;background:#f1f5fa;line-height:1.5}
*{box-sizing:border-box}body{max-width:1540px;margin:0 auto;padding:26px 28px 40px}h1,h2,h3,p{margin:0}h1{font-size:25px;letter-spacing:.5px}h2{font-size:16px;margin-bottom:15px}h3{font-size:13px;margin:14px 0 7px}
header,.row,.actions,.heading{display:flex;align-items:center;gap:12px;justify-content:space-between}.brand{display:flex;align-items:center;gap:13px}.logo{display:grid;place-items:center;background:#2258bd;color:white;border-radius:13px;width:47px;height:47px;font-size:25px;font-weight:700}.muted{color:#677b91;font-size:13px}.eyebrow{color:#5a7190;letter-spacing:1.5px;font-size:11px;font-weight:700}
.pill,.badge{display:inline-block;padding:5px 11px;border-radius:20px;font-size:12px;background:#e6edf7;color:#365271;white-space:nowrap}.badge{font-weight:700}.good{background:#dcf4e7;color:#137343}.bad{background:#fde6e6;color:#af3540}.warn{background:#fff0d5;color:#91600a}.panel{background:white;border:1px solid #dfe7ef;border-radius:15px;padding:22px;box-shadow:0 3px 14px #17344d04}
.task{margin:23px 0 16px}.task textarea{width:100%;min-height:78px;border:1px solid #cfdbe8;border-radius:10px;padding:13px 15px;font:inherit;font-size:16px;resize:vertical;outline-color:#3370d4}.consent{font-size:12px;color:#60748b;display:flex;gap:7px;margin:10px 0 4px}.consent input{flex:none}.actions{justify-content:flex-start;flex-wrap:wrap}.actions small{margin-left:auto;color:#677b91}
button,a.button{font:inherit;font-size:13px;padding:9px 16px;border:1px solid #cbd7e6;border-radius:8px;background:white;color:#26435f;cursor:pointer;text-decoration:none;display:inline-block}button.primary{background:#255fc3;color:white;border-color:#255fc3}button.danger{color:#b23542}button:disabled{opacity:.45;cursor:default}button:hover:enabled,a.button:hover{filter:brightness(.96)}
.grid{display:grid;grid-template-columns:235px minmax(300px,1fr) minmax(330px,1.15fr);gap:16px;align-items:start}.sidebar .field{padding:12px 0;border-bottom:1px solid #edf1f6}.field span{display:block;font-size:11px;color:#71849b;margin-bottom:4px}.field strong{font-size:13px;font-weight:600;overflow-wrap:anywhere}.sidebar .field:last-child{border:0}
.stage{display:flex;gap:10px;align-items:center;margin:9px 0 17px;padding:12px;background:#f1f6ff;border-radius:9px;color:#2457a2}.dot{height:9px;width:9px;border-radius:50%;background:#3375d1;flex:none}.busy .dot{animation:pulse 1.2s infinite}@keyframes pulse{50%{opacity:.25}}
.steps{padding:0;list-style:none;margin:0}.steps li{display:flex;gap:11px;padding:10px 0;color:#8291a3;font-size:13px;align-items:center}.steps b{width:23px;height:23px;flex:none;border-radius:50%;display:grid;place-items:center;background:#eef2f7;font-size:11px;font-weight:400}.steps li.done{color:#1d6e4b}.steps li.done b{background:#e0f2e7}.steps li.active{color:#245fc0;font-weight:600}.steps li.active b{background:#e4efff}.steps li.failed{color:#b23542}.steps li.failed b{background:#fde5e5}
.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:16px 0}.metric{background:#f4f7fb;border-radius:10px;padding:13px 12px}.metric .value{font-size:23px;line-height:1.2;font-weight:650;margin:8px 0;overflow-wrap:anywhere}.metric small{color:#72849a;font-size:11px}.metric span{font-size:11px;color:#71849b}.metric.target{background:#eaf1ff}.reason{white-space:pre-wrap;overflow-wrap:anywhere;color:#334e68;font-size:14px;min-height:50px}.notice{padding:11px 13px;border-radius:9px;background:#f2f6fb;font-size:13px;margin:10px 0}.error{color:#b12f3e;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:10px;font-size:13px}
pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fb;padding:13px;border-radius:9px;max-height:430px;overflow:auto;font-family:Consolas,"Microsoft YaHei",monospace;font-size:12px;tab-size:4}#diff{background:#142b3e;color:#e0ecf4;border:1px solid #203d54;min-height:72px}#review{margin-top:15px;border-top:1px solid #e5ebf3;padding-top:17px}#review-title{margin-bottom:9px}
.results{margin-top:16px}.rounds{width:100%;border-collapse:collapse;font-size:13px}.rounds th{text-align:left;color:#75879b;font-weight:500}.rounds td,.rounds th{padding:10px;border-bottom:1px solid #e8eef5}.history{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:16px}select{max-width:350px;border:1px solid #cbd7e6;border-radius:7px;padding:8px;background:white;color:#476079}details{margin-top:17px}summary{cursor:pointer;color:#55718e;font-size:12px}.hidden{display:none!important}footer{margin-top:18px;color:#8090a2;font-size:11px}
.report-identity{display:grid;gap:4px;margin:10px 0;font-size:12px;color:#60748b}.report-identity code{color:#26435f;overflow-wrap:anywhere}
@media(max-width:1150px){.grid{grid-template-columns:220px 1fr}.analysis{grid-column:1/-1}}@media(max-width:700px){body{padding:18px 12px}.grid{display:block}.panel{margin-bottom:13px;padding:17px}.metrics .value{font-size:18px}header{align-items:start}.actions small{margin-left:0}.sidebar{display:block}h1{font-size:19px}}
</style>
<header><div class="brand"><div class="logo">智</div><div><p class="eyebrow">ZHITIAO / HARDWARE AGENT</p><h1>智调 · AI 硬件调试控制台</h1></div></div><div><span id="mode" class="pill">本地控制台</span> <span id="verdict" class="badge">准备就绪</span></div></header>
<section class="panel task"><div class="heading"><h2>用一句话描述你的目标</h2><span id="attempt" class="muted">最多 3 轮</span></div>
<textarea id="task" placeholder="把 STM32 PA1 的完整周期调到 1000 ms，误差不超过 50 ms。"></textarea>
<p id="model-notice" class="muted"></p>
<label class="consent"><input id="consent" type="checkbox">同意向已配置模型发送任务、白名单源码及运行证据；每次新源码修改仍需我审阅批准。</label>
<div class="actions"><button id="start" class="primary">分析目标</button><button id="cancel" class="danger">停止运行</button><small id="mode-note">任务范围与每次源码 diff 均有明确授权。</small></div><p id="error" class="error"></p>
<div id="uncertain" class="notice warn hidden">操作可能在板端继续运行。请先人工确认烧录 / FPGA 状态，再开始新任务。</div></section>
<main class="grid"><aside class="panel sidebar"><h2>部署与任务范围</h2>
<div class="field"><span>工程 / Project</span><strong id="project"></strong></div><div class="field"><span>可修改源码</span><strong id="sources"></strong></div><div class="field"><span>编译 Target</span><strong id="target-name"></strong></div><div class="field"><span>物理证据</span><strong id="channels"></strong></div><div class="field"><span>模型</span><strong id="model-name">已配置模型</strong></div><div class="field"><span>审批模式</span><strong id="approval-mode"></strong></div>
<details><summary>高级部署信息</summary><pre id="scope"></pre></details></aside>
<section class="panel"><div class="heading"><h2>工作流</h2><span id="status" class="pill">IDLE</span></div><div id="stage" class="stage"><i class="dot"></i><span id="stage-label">等待任务</span></div><ol id="steps" class="steps"></ol>
<div id="clarification" class="hidden"><h3>请补充目标</h3><p id="question" class="reason"></p><textarea id="answer" maxlength="1000"></textarea><button id="clarify" class="primary">发送补充说明</button></div>
<h3 id="uart-title">UART 日志</h3><pre id="uart">尚未采集。</pre><p id="uart-note" class="muted">空日志可以是成功采集；GPIO 周期由 PL 独立判定。</p></section>
<section class="panel analysis"><div class="heading"><h2>物理证据与 AI 修改建议</h2><span id="evidence" class="pill">真实硬件</span></div>
<div class="metrics"><div class="metric"><small>BEFORE · 初次测量</small><div id="before" class="value">—</div><span id="before-verdict">等待基线</span></div><div class="metric target"><small>TARGET · 目标</small><div id="goal-value" class="value">—</div><span id="goal-tolerance">等待理解目标</span></div><div class="metric"><small>AFTER · 修改后测量</small><div id="after" class="value">—</div><span id="after-verdict">等待重新验证</span></div></div>
<h3>AI 分析摘要</h3><p id="reason" class="reason">取得实测证据后，AI 会说明原因并提出修改。PASS 由确定性测量规则判定。</p>
<div id="review" class="hidden"><h2 id="review-title">审阅当前操作</h2><p id="review-explain" class="notice"></p><h3>完整源码差异</h3><pre id="diff"></pre><div class="actions"><button id="approve" class="primary">批准当前操作</button><button id="reject" class="danger">拒绝并停止</button></div><details><summary>查看本项完整计划与绑定信息</summary><pre id="plan"></pre></details></div>
</section></main>
<section class="panel results"><div class="heading"><h2>轮次结果与报告</h2><a class="button" href="/api/report" download="zhidiao-run.json">下载当前 JSON 报告</a></div><table class="rounds"><thead><tr><th>轮次</th><th>PL 完整周期</th><th>偏差</th><th>确定性判定</th></tr></thead><tbody id="rounds"></tbody></table>
<div class="report-identity" aria-live="polite"><span>当前运行报告 ID：<code id="current-run-id">尚未生成报告</code></span><span>历史所选报告 ID：<code id="selected-run-id">未选择</code></span></div>
<p class="muted">轮次结果、下载当前 JSON 与下方审计详情对应当前运行报告。历史选择用于下载或从检查点继续，不会切换当前展示。</p>
<div class="history"><button id="history">刷新历史</button><label for="runs" class="muted">历史报告</label><select id="runs"></select><a id="old-report" class="button">下载所选报告</a><button id="resume">从所选检查点继续</button></div><details><summary>开发 / 审计详情（完整 JSON）</summary><pre id="report"></pre></details></section>
<footer>只允许所选工程与源码范围；真实硬件与演示证据明确区分。关闭浏览器窗口不会停止服务，请用“停止运行”或终端 Ctrl+C。</footer>
<script nonce="__NONCE__">
const csrf='__CSRF__';let current=null,clientError='';
function visible(value){return String(value).replace(/[\\p{Cc}\\p{Cf}]/gu,c=>[9,10].includes(c.codePointAt(0))?c:String.fromCharCode(92)+'u'+c.codePointAt(0).toString(16).padStart(4,'0'));}
const el=id=>document.getElementById(id), text=(id,value)=>el(id).textContent=value==null?'':visible(value);
function node(tag,value,cls){const n=document.createElement(tag);n.textContent=visible(value);if(cls)n.className=cls;return n;}
function ms(value){return typeof value==='number'&&Number.isFinite(value)?value.toFixed(3)+' ms':'—';}
function badge(id,label,kind){text(id,label);el(id).className='badge '+kind;}
async function post(path,body){try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});const result=await response.json();clientError=result.success?'':result.message;await refresh();}catch(_){clientError='本地服务请求失败，请检查启动终端。';text('error',clientError);}}
function renderSteps(s){el('steps').replaceChildren();for(const [i,step] of (s.view.steps||[]).entries()){const row=document.createElement('li');row.className=step.state;const marker=step.state==='done'?'✓':step.state==='failed'?'!':step.state==='skipped'?'—':i+1;row.append(node('b',marker),node('span',step.label));el('steps').appendChild(row);}}
function render(s){const v=s.view||{},p=s.pending,scope=s.scope||{},goal=v.goal;
if(s.task&&!el('task').value)el('task').value=s.task;
text('project',scope.project_path);text('sources',Array.isArray(scope.source_files)?scope.source_files.join('、'):Object.keys(scope.source_files||{}).join('、'));text('target-name',(scope.target||'所选 Target')+(scope.target_host?' · '+scope.target_host:''));text('channels',(scope.observed_gpio||'PA1')+' / '+scope.observation_mode+(scope.uart_channel?' · '+scope.uart_channel:''));text('model-name',scope.model||'已配置模型');text('approval-mode',scope.approval_mode==='semantic'?'会话范围＋每个源码 diff':'严格模式 · 每轮再次批准');text('scope',JSON.stringify(scope,null,2));
text('mode',scope.evidence_source==='mock'?(scope.model_source==='nicecode_api'?'NiceCode API · 模拟硬件':'演示模式 · 模拟硬件'):'真实硬件模式');text('model-notice',scope.model_source==='nicecode_api'?'真实 NiceCode API＋模拟硬件：请求可能计费；仅编辑临时 main.c，UART／PL 均为模拟证据。':scope.model_source==='scripted'?'离线脚本演示：模型与硬件均为模拟，不调用 NiceCode。':'');text('evidence',v.evidence_source==='mock'?'模拟证据':v.evidence_source==='none'?'暂无测量证据':'PL 独立物理证据');text('attempt','当前 '+(v.attempt||0)+' / '+(v.max_attempts||3)+' 轮');text('status','第 '+(v.attempt||0)+' 轮');text('stage-label',v.stage_label||'等待任务');el('stage').classList.toggle('busy',s.busy);badge('verdict',v.status_label||s.phase,v.status==='PASS'?'good':v.status==='ERROR'||v.status==='FAIL'?'bad':s.busy?'warn':'');
text('error',clientError||(s.last_result&&!s.last_result.success?s.last_result.message:!s.preflight.success?s.preflight.message:''));el('uncertain').classList.toggle('hidden',!v.hardware_state_uncertain);text('before',ms(v.before&&v.before.period_ms));text('before-verdict',v.before?(v.before.passed?'PASS · 基线已达标':'FAIL · 基线未达标'):'等待基线');text('after',ms(v.after&&v.after.period_ms));text('after-verdict',v.after?(v.after.passed?'PASS · 已通过':'FAIL · 继续分析 / 到限停止'):'等待重新验证');text('goal-value',goal?ms(goal.expected_period_ms):'—');text('goal-tolerance',goal?'容差 ±'+goal.tolerance_ms+' ms':'等待理解目标');text('reason',v.reason||(scope.evidence_source==='mock'?'取得模拟证据后，AI 会说明原因并提出修改。PASS 由模拟测量规则判定。':'取得实测证据后，AI 会说明原因并提出修改。PASS 由确定性测量规则判定。'));const u=v.latest_uart,waiting=u&&u.attempt>(v.uart_attempt||0);text('uart-title','UART 日志'+(waiting?' · 第 '+u.attempt+' 轮':v.uart_attempt?' · 第 '+v.uart_attempt+' 轮':''));text('uart',v.uart_text||'尚未采集。');
el('clarification').classList.toggle('hidden',s.phase!=='NEEDS_CLARIFICATION');text('question',s.question);el('review').classList.toggle('hidden',!p);
if(p){const edit=s.phase==='AWAITING_APPROVAL',session=p.action==='run_session';text('review-title',edit?'审阅 AI 源码修改':session?'批准任务范围并开始':s.phase==='AWAITING_GOAL_APPROVAL'?'确认目标':'批准本轮真实验证');text('review-explain',edit?(scope.approval_mode==='semantic'?'批准后仅应用下方差异，并自动重新构建、烧录、采集与验证。':'批准后应用下方差异；硬件验证仍会单独确认。'):session?'允许所选工程在当前目标、板卡与最多轮次范围内执行。每次新源码修改仍须再次批准。':'请核对目标、所选工程和验证范围。');text('diff',p.params&&p.params.diff||'本项没有源码修改。');if(v.fifo_reset_planned)text('review-explain',el('review-explain').textContent+' 本轮采集前会清空 UART RX FIFO，排除旧日志。');if(v.fpga_reload_planned)text('review-explain',el('review-explain').textContent+' 本轮将校验并重新加载已配置 FPGA 镜像，替换当前 PL 配置。');text('plan',JSON.stringify(p.params,null,2));text('approve',edit&&scope.approval_mode==='semantic'?'批准修改并重新验证':session?'批准范围并开始':'批准当前操作');}
el('rounds').replaceChildren();for(const point of v.measurements||[]){const row=document.createElement('tr');row.append(node('td','Attempt '+point.attempt),node('td',ms(point.period_ms)),node('td',goal?ms(Math.abs(point.period_ms-goal.expected_period_ms)):'—'),node('td',point.passed?'PASS':'FAIL',point.passed?'good':'bad'));el('rounds').appendChild(row);}if(!(v.measurements||[]).length){const row=document.createElement('tr'),cell=node('td','尚无物理测量结果。');cell.colSpan=4;row.appendChild(cell);el('rounds').appendChild(row);}
text('current-run-id',(s.report||{}).run_id||'尚未生成报告');text('report',JSON.stringify(s.report||{},null,2));renderSteps(s);const disabled=s.busy||s.closing;el('start').disabled=disabled||!s.preflight.success||!['IDLE','PASS','FAIL','STOPPED'].includes(s.phase);el('resume').disabled=el('start').disabled;el('clarify').disabled=disabled;el('approve').disabled=disabled||!p;el('reject').disabled=disabled||!p;el('cancel').disabled=s.closing;}
async function refresh(){try{const response=await fetch('/api/state');const result=await response.json();if(!result.success){text('error',result.message);return;}current=result;render(result.state);}catch(_){text('error','本地服务不可用，请检查终端。');}}
el('start').onclick=()=>{const consent=el('consent').checked;el('consent').checked=false;post('/api/start',{task:el('task').value,share_context:consent});};el('clarify').onclick=()=>post('/api/clarify',{answer:el('answer').value});
function review(approved){const p=current&&current.state.pending;if(p)post('/api/review',{proposal_id:p.proposal_id,fingerprint:p.fingerprint,approved});}
el('approve').onclick=()=>review(true);el('reject').onclick=()=>review(false);el('cancel').onclick=()=>post('/api/cancel',{});
async function history(){try{const response=await fetch('/api/runs'),data=await response.json();el('runs').replaceChildren();for(const id of data.runs||[]){const option=node('option',id);option.value=id;el('runs').appendChild(option);}selectRun();}catch(_){text('error','读取本地报告目录失败。');}}
function selectRun(){text('selected-run-id',el('runs').value||'未选择');el('old-report').href='/api/report/'+encodeURIComponent(el('runs').value);el('old-report').download=el('runs').value+'.json';}
el('history').onclick=history;el('runs').onchange=selectRun;el('resume').onclick=()=>{const consent=el('consent').checked;el('consent').checked=false;post('/api/resume',{run_id:el('runs').value,share_context:consent});};
refresh();setInterval(refresh,1000);
</script></html>'''
